head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71301";
scwin.form = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — isOk

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71301.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String((dma_pageContext.get("totalCountIntValue") ?? "")) + "건 [" + String((dma_pageContext.get("currentPage") ?? "")) + "/" + String((dma_pageContext.get("totalPageCount") ?? "")) + "Page]"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(digitalcommonnotilist#getdigitalcommonnotilist vs digitalcommonnotilist#editdigitalcommonnoti) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_clmSchdlNoti_oncellclick
 * @description grd_clmSchdlNoti 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_clmSchdlNoti_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_clmSchdlNoti');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_clmSchdlNoti */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { await scwin.openAdjReqPop(r["bzProcsNo"], "220"); return; } if (r["assgnYn"] ==='Y') { await scwin.editDigitalNoti(r["bzProcsNo"], "32", r["assgnYn"]); return; } return; } if (r["listProcsStatCd"] !== '30' && r["listProcsStatCd"] !== '37' && r["listProcsStatCd"] !== '35') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        if (r["listProcsStatCd"] === '30') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        if (r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        if (r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["bzProcsNo"]); return; }
        await scwin.viewDetail(r["bzProcsNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_clmSchdlNoti.oncellclick' });
    }
};

/**
 * @method
 * @name btn_newWrite_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_newWrite_onclick = function(e){
    try {
        scwin.newWrite()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71301.btn_newWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_72_onclick
 * @description krxpage_pagenavigator_72 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_72_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_72.page' }); } await scwin.fncSearch(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/digital/DigitalCommonNotiList.do",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/digital/DigitalCommonNoti.do",
        ref: "dma_viewDetailReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_editDigitalNoti
 * @description edit Digital Noti 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_editDigitalNoti = async function () {
    const sbmOptions = {
        id: "tx_editDigitalNoti",
        method: "post",
        action: "/digital/DigitalCommonNotiList.do?method=editDigitalCommonNoti",
        ref: "dma_editDigitalNotiReq",
        target: "dlt_clmSchdlNoti=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_clmSchdlNoti_fillAct
 * @description grd clm Schdl Noti fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_clmSchdlNoti_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_clmSchdlNoti');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["assgnYn"] ==='Y') { v = "제출"; } else if (r["listProcsStatCd"] === '33'|| r["listProcsStatCd"] === '36') { v = "수정요청"; } else if (r["assgnYn"] ==='Y') { v = "제출"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_clmSchdlNoti.fillAct' });
    }
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    scwin.form = (document.prelistPageForm || { elements: [] });
    const pageIndex = $c.util.getComponent('dma_searchCorpListByBeginIndexReq').get('pageIndex');
    $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    scwin.form.action = "/digital/DigitalCommonNotiList.do";
    $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('method', 'getDigitalCommonNotiList');
    await scwin.tx_searchCorpListByBeginIndex();
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (bzProcsNo) {
    scwin.form = (document.prelistPageForm || { elements: [] });
    $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('bzProcsNo', bzProcsNo);
    scwin.form.action = '/digital/DigitalCommonNoti.do';
    $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('method', 'editForm');
    const nr = await scwin.tx_viewDetail();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil71302/jldfil71302.xml", { "bzProcsNo": bzProcsNo, "method": 'editForm' });
    }
};

/**
 * @method
 * @name newWrite
 * @description new Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil71302/jldfil71302.xml');
    return false;
};

/**
 * @method
 * @name editDigitalNoti
 * @description edit Digital Noti 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} status status
 * @param {String} assgnYn assgnYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.editDigitalNoti = async function (bzProcsNo, status, assgnYn) {
    scwin.form = (document.prelistPageForm || { elements: [] });
    scwin.form.action = "/digital/DigitalCommonNotiList.do?method=editDigitalCommonNoti";
    $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('status', status);
    $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('bzProcsNo', bzProcsNo);
    if (assgnYn === 'Y') {
        if (await $c.win.confirm('제출하시겠습니까?')) {
            await scwin.tx_editDigitalNoti();
        }
    } else {
        await $c.win.alert('제출은 ID배정 이후에 가능합니다.');
        return;
    }
};

/**
 * @method
 * @name getSearch
 * @description get Search 처리
 * @param {*} strType strType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getSearch = async function (strType) {
    $c.util.getComponent('dma_searchCorpListByBeginIndexReq').set('popCheck', strType);
    await scwin.fncSearch();
};

/**
 * @method
 * @name defaultCheck
 * @description default Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.defaultCheck = async function () {
    isOk = (String(((dma_pageContext.get("isOk") ?? "")) === null ? '' : ((dma_pageContext.get("isOk") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("isOk") ?? "")) === null ? '' : ((dma_pageContext.get("isOk") ?? ""))));
    if (isOk !== '') {
        if (isOk) {
            await $c.win.alert('제출되었습니다');
        } else {
            await $c.win.alert('제출시 오류가 발생했습니다.');
        }
        await scwin.fncSearch();
    }
};

/**
 * @method
 * @name openAdjReqPop
 * @description open Adj Req Pop 처리
 * @param {*} prtdepoNo prtdepoNo
 * @param {String} listInvstgBzTpCd listInvstgBzTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqPop = async function (prtdepoNo, listInvstgBzTpCd) {
    const data = { bzProcsNo: prtdepoNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: "23", callbackFn: "scwin.popupCallback" };
    const options = { id: "jldfil59411", popupName: "상장공시제출시스템 수정요청", width: 900, height: 380, frameModal: "top" };
    await $c.win.openPopup("/jldfil59411/jldfil59411.xml", options, data);
};
